{
  "name": "opencode-subagent-usage",
  "version": "0.1.1",
  "description": "opencode TUI sidebar widget showing the rolled-up cost and token usage of subagent (child) sessions.",
  "type": "module",
  "license": "MIT",
  "author": "JLegends",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/JLegends/opencode-subagent-usage.git"
  },
  "homepage": "https://github.com/JLegends/opencode-subagent-usage#readme",
  "bugs": {
    "url": "https://github.com/JLegends/opencode-subagent-usage/issues"
  },
  "exports": {
    "./tui": {
      "import": "./src/subagent-usage.js"
    }
  },
  "files": [
    "src",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tui",
    "subagent",
    "cost",
    "tokens",
    "observability"
  ],
  "engines": {
    "opencode": ">=1.18.31"
  },
  "peerDependencies": {
    "@opentui/solid": ">=0.4.5",
    "solid-js": "^1.9.0"
  },
  "peerDependenciesMeta": {
    "@opentui/solid": {
      "optional": true
    },
    "solid-js": {
      "optional": true
    }
  },
  "scripts": {
    "check": "node --check src/subagent-usage.js"
  }
}
